import{R as r,e as i,f as a,U as l}from"./chunks/framework.BKStFnx-.js";const h=JSON.parse('{"title":"Fields","description":"","frontmatter":{},"headers":[],"relativePath":"browser/ui-reference/fields/index.md","filePath":"browser/ui-reference/fields/index.md","lastUpdated":1778046378000}'),s={name:"browser/ui-reference/fields/index.md"};function o(t,e,n,f,d,c){return i(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="fields" tabindex="-1">Fields <a class="header-anchor" href="#fields" aria-label="Permalink to &quot;Fields&quot;">​</a></h1><p>Field pages document the browser-owned contract for rendered Formie fields.</p><p>That includes:</p><ul><li>a visual preview of the default output</li><li>required attributes and which element they belong to when overriding markup</li><li>optional styling classes</li><li>browser hooks and events when a field has browser behavior</li><li>token and accessibility notes for common overrides</li></ul><p>For full Twig overrides, start with <a href="/formie/browser/ui-reference/components/form">Form</a> and <a href="/formie/browser/ui-reference/components/field">Field</a> before drilling into the field-specific pages.</p><p>Normal Formie-rendered output already includes these hooks for you. The attribute tables on these pages matter most when you are overriding templates, auditing generated markup, or mapping the default UI into another rendering surface.</p><p>Those requirements often span more than one element: a field wrapper, one or more form controls, and sometimes supporting nodes such as hidden inputs, error containers, or subfield rows. The field pages should call out that ownership explicitly rather than imply everything belongs on a single element.</p><h2 id="field-reference-pages" tabindex="-1">Field reference pages <a class="header-anchor" href="#field-reference-pages" aria-label="Permalink to &quot;Field reference pages&quot;">​</a></h2><ul><li><a href="/formie/browser/ui-reference/fields/single-line-text">Single Line Text</a></li><li><a href="/formie/browser/ui-reference/fields/multi-line-text">Multi Line Text</a></li><li><a href="/formie/browser/ui-reference/fields/checkboxes">Checkboxes</a></li><li><a href="/formie/browser/ui-reference/fields/radio">Radio</a></li><li><a href="/formie/browser/ui-reference/fields/agree">Agree</a></li><li><a href="/formie/browser/ui-reference/fields/date">Date</a></li><li><a href="/formie/browser/ui-reference/fields/phone">Phone</a></li><li><a href="/formie/browser/ui-reference/fields/address">Address</a></li><li><a href="/formie/browser/ui-reference/fields/categories">Categories</a></li><li><a href="/formie/browser/ui-reference/fields/file-upload">File Upload</a></li><li><a href="/formie/browser/ui-reference/fields/entries">Entries</a></li><li><a href="/formie/browser/ui-reference/fields/signature">Signature</a></li><li><a href="/formie/browser/ui-reference/fields/tags">Tags</a></li><li><a href="/formie/browser/ui-reference/fields/repeater">Repeater</a></li><li><a href="/formie/browser/ui-reference/fields/table">Table</a></li><li><a href="/formie/browser/ui-reference/fields/summary">Summary</a></li><li><a href="/formie/browser/ui-reference/fields/calculations">Calculations</a></li><li><a href="/formie/browser/ui-reference/fields/recipients">Recipients</a></li><li><a href="/formie/browser/ui-reference/fields/hidden">Hidden</a></li><li><a href="/formie/browser/ui-reference/fields/payment">Payment</a></li></ul><h2 id="field-categories" tabindex="-1">Field categories <a class="header-anchor" href="#field-categories" aria-label="Permalink to &quot;Field categories&quot;">​</a></h2><p>The browser package field surface broadly falls into these groups:</p><ul><li>core inputs such as single-line text, multi-line text, radio, checkboxes, and agree</li><li>element-backed choice fields such as categories, entries, and recipients</li><li>enhanced inputs such as date, phone, tags, file upload, and signature</li><li>structural fields such as repeater and table</li><li>derived fields such as summary, calculations, and hidden values</li><li>provider-backed fields such as address and payment</li></ul><p>As more field pages are promoted into the public reference set, they should follow the same structure and stay owned by the Browser docs rather than a separate “core” docs area.</p><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="/formie/browser/ui-reference/components/form">Form</a></li><li><a href="/formie/browser/ui-reference/components/field">Field</a></li><li><a href="/formie/browser/ui-reference/components/buttons">Buttons</a></li><li><a href="/formie/browser/ui-reference/components/loading">Loading</a></li><li><a href="/formie/browser/ui-reference/css-variables">CSS variables</a></li><li><a href="/formie/browser/behavior/javascript-events">JavaScript events</a></li></ul>',15)])])}const m=r(s,[["render",o]]);export{h as __pageData,m as default};
